#include <bits/stdc++.h>
using namespace std;

static char ibuf[1 << 16];
static size_t ilen = 0, ipos = 0;

static inline int gc() {
    if (ipos == ilen) {
        ilen = fread(ibuf, 1, sizeof ibuf, stdin);
        ipos = 0;
        if (ilen == 0) return -1;
    }
    return ibuf[ipos++];
}

static long long readInt() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    bool neg = c == '-';
    if (neg) c = gc();
    long long v = 0;
    while (c >= '0' && c <= '9') {
        v = v * 10 + (c - '0');
        c = gc();
    }
    return neg ? -v : v;
}

static string readToken() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    string s;
    while (c > ' ') {
        s.push_back((char)c);
        c = gc();
    }
    return s;
}

int main() {
    string s = readToken();
    // Each pair of adjacent runs contributes min(previous run, current run).
    long long prev = 0, run = 0, answer = 0;
    char last = 0;
    for (char ch : s) {
        if (ch == last) run++;
        else {
            answer += min(prev, run);
            prev = run;
            run = 1;
            last = ch;
        }
    }
    printf("%lld\n", answer + min(prev, run));
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        long prev = 0, run = 0, answer = 0;
        char last = 0;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == last) run++;
            else {
                answer += Math.min(prev, run);
                prev = run;
                run = 1;
                last = ch;
            }
        }
        System.out.println(answer + Math.min(prev, run));
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := token()
	prev, run, answer := 0, 0, 0
	var last byte
	for _, ch := range s {
		if ch == last {
			run++
		} else {
			answer += min(prev, run)
			prev, run, last = run, 1, ch
		}
	}
	fmt.Println(answer + min(prev, run))
}
